test("cancel statement scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms-B", "3");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25"})).toBeNull();
  expect(await ui.periodAction(pg_uma, "P2", "close")).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "7.77", "date": "2026-03-15"})).toBeNull();
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-03-01", "to": "2026-03-28"})).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25"})).toBeNull();
  expect(await ui.watch(pg_uma, p_ben, true)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.periodAction(pg_wes, "P1", "reopen")).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.periodAction(pg_wes, "P1", "close")).toBe(true);
  expect(await ui.quickAdd(pg_wes, {"name": "Dot", "amount": "12.50"})).toBeNull();
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("sheet-archived")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-name")).toHaveText("Ada");
test("cancel statement scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-open", "clerk");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  await ui.setToday(pg_uma, "2026-03-27");
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  const c_ben_0 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "25.00", "date": "2026-03-05"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "20.00", "date": "2026-03-20"}));
  expect(await ui.hold(pg_vic, p_ben, {"from": "2026-02-25", "to": "2026-03-15"})).toBe(true);
  await ui.refresh(pg_vic);
  const c_ben_1 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "12.50", "date": "2026-03-15"}));
  expect(await ui.statement(pg_vic, p_cam)).toBe(true);
  expect(await ui.addPatron(pg_vic, p_ben, "Ada")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  const c_ada_1 = ui.must(await ui.addClaimTwice(pg_wes, p_ada, {"amount": "10.25", "date": "2026-03-09"}));
